"use client";

import type { Node, NodeProps } from "@xyflow/react";
import type { CSSProperties } from "react";
import type { RegionNodeData } from "./types";

export type ArchitectureRegionNode = Node<RegionNodeData, "region">;

export default function RegionNode({ data }: NodeProps<ArchitectureRegionNode>) {
  const { region, emphasis, zoomLevel, zoom, objectCount, childRegionCount, keyObjectNames, depth } = data;
  const labelScale = zoomLevel === "landscape"
    ? Math.min(4.2, Math.max(1, 0.94 / Math.max(zoom, 0.16)))
    : zoomLevel === "architecture"
      ? Math.min(2.4, Math.max(1, 0.84 / Math.max(zoom, 0.42)))
      : 1;
  return (
    <section
      aria-label={`Region ${region.name}`}
      className={`canvas-region depth-${Math.min(depth, 3)} emphasis-${emphasis} zoom-${zoomLevel}`}
      style={{ "--region-label-scale": labelScale } as CSSProperties}
    >
      <header>
        <span>Region</span>
        <strong>{region.name}</strong>
        <small>{objectCount} objects{childRegionCount > 0 ? ` · ${childRegionCount} regions` : ""}</small>
      </header>
      {zoomLevel === "landscape" && (
        <div className="region-landscape-summary">
          <p>{region.summary || "Declared system boundary"}</p>
          {keyObjectNames.length > 0 && <span>{keyObjectNames.join(" · ")}</span>}
        </div>
      )}
    </section>
  );
}

