7	  type Edge,
8	  type EdgeProps,
9	} from "@xyflow/react";
10	import { useSmartEdgePath } from "@tisoap/react-flow-smart-edge";
11	import type { CSSProperties } from "react";
12	import type { RelationshipEdgeData } from "./types";
13	
14	export type ArchitectureFlowEdge = Edge<RelationshipEdgeData, "relationship">;
15	
16	function roundedOrthogonalPath(points: Array<{ x: number; y: number }>, radius = 8) {
17	  if (points.length < 2) return "";
18	  let path = `M ${points[0].x} ${points[0].y}`;
19	  for (let index = 1; index < points.length - 1; index += 1) {
20	    const previous = points[index - 1];
21	    const current = points[index];
22	    const next = points[index + 1];
23	    const incomingLength = Math.hypot(current.x - previous.x, current.y - previous.y);
24	    const outgoingLength = Math.hypot(next.x - current.x, next.y - current.y);
25	    const corner = Math.min(radius, incomingLength / 2, outgoingLength / 2);
26	    if (!corner || (previous.x === current.x && current.x === next.x) || (previous.y === current.y && current.y === next.y)) {
27	      path += ` L ${current.x} ${current.y}`;
28	      continue;
29	    }
30	    const before = {
31	      x: current.x - ((current.x - previous.x) / incomingLength) * corner,
32	      y: current.y - ((current.y - previous.y) / incomingLength) * corner,
33	    };
34	    const after = {
35	      x: current.x + ((next.x - current.x) / outgoingLength) * corner,
36	      y: current.y + ((next.y - current.y) / outgoingLength) * corner,
37	    };
38	    path += ` L ${before.x} ${before.y} Q ${current.x} ${current.y} ${after.x} ${after.y}`;
39	  }
40	  const last = points.at(-1)!;
41	  return `${path} L ${last.x} ${last.y}`;
42	}
43	
44	export default function RelationshipEdge(props: EdgeProps<ArchitectureFlowEdge>) {
45	  const smart = useSmartEdgePath({
46	    id: props.id,
47	    source: props.source,
48	    target: props.target,
