import type { CanvasMode } from "./interaction";

export const CANVAS_VIEWPORT_CONTRACT = {
  browse: { padding: 0.12, minZoom: 0.58, maxZoom: 0.9 },
  inspect: { padding: 0.34, minZoom: 0.62, maxZoom: 1.02 },
  focus: { padding: 0.42, minZoom: 0.62, maxZoom: 1.08 },
  trace: { padding: 0.28, minZoom: 0.58, maxZoom: 0.88 },
} as const;

export type CanvasFitKind = CanvasMode;

export function canvasFitOptions(kind: CanvasFitKind, duration = 360) {
  return { ...CANVAS_VIEWPORT_CONTRACT[kind], duration };
}

export function minimumScreenObjectWidth(
  objectRects: Record<string, { width: number }>,
  zoom: number,
) {
  const widths = Object.values(objectRects).map((rect) => rect.width * zoom);
  return widths.length > 0 ? Math.min(...widths) : 0;
}

export function canvasLayoutAspectRatio(width: number, height: number) {
  if (width <= 0 || height <= 0) return 1;
  const ratio = width / height;
  return Math.max(ratio, 1 / ratio);
}

