5	register("./cloudflare-loader.mjs", import.meta.url);
6	
7	const {
8	  CANVAS_FIXTURES,
9	  COMPLEX_CANVAS_FIXTURE,
10	  LARGE_CANVAS_FIXTURE,
11	  MEDIUM_CANVAS_FIXTURE,
