"""Direct stdio JSON-RPC bridge to prax-mcp.

The Claude Code harness zod layer rejects design_start's anyOf parameter root,
so calls are sent as raw MCP JSON-RPC over stdio instead.

Usage:
  python prax_call.py --list                 # dump all tool inputSchemas to prax_tools.json
  python prax_call.py <tool> '<args-json>'   # call a tool; auto-injects design_session_id
  python prax_call.py <tool> '<args>' --no-session  # skip session injection
"""

import json
import shutil
import subprocess
import sys
import threading
import time
from pathlib import Path

HERE = Path(__file__).resolve().parent
SESSION_FILE = HERE / "prax_session.json"
TOOLS_FILE = HERE / "prax_tools.json"
PROTOCOL = "2024-11-05"


def spawn():
    exe = shutil.which("prax-mcp") or shutil.which("prax-mcp.cmd") or "prax-mcp"
    return subprocess.Popen(
        [exe],
        stdin=subprocess.PIPE,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        encoding="utf-8",
        bufsize=1,
    )


def send(proc, payload):
    proc.stdin.write(json.dumps(payload) + "\n")
    proc.stdin.flush()


def wait_response(proc, want_id, timeout=600):
    result = {}

    def pump():
        for line in proc.stdout:
            line = line.strip()
            if not line:
                continue
            try:
                message = json.loads(line)
            except json.JSONDecodeError:
                continue
            if message.get("id") == want_id:
                result["message"] = message
                return

    thread = threading.Thread(target=pump, daemon=True)
    thread.start()
    deadline = time.time() + timeout
    while thread.is_alive() and time.time() < deadline:
        time.sleep(0.1)
    return result.get("message")


def call_tool(name, arguments):
    proc = spawn()
    try:
        send(proc, {"jsonrpc": "2.0", "id": 1, "method": "initialize", "params": {
            "protocolVersion": PROTOCOL,
            "capabilities": {},
            "clientInfo": {"name": "prax-bypass", "version": "1.0"},
        }})
        if not wait_response(proc, 1):
            raise RuntimeError("initialize timed out")
        send(proc, {"jsonrpc": "2.0", "method": "notifications/initialized"})
        send(proc, {"jsonrpc": "2.0", "id": 2, "method": "tools/call", "params": {"name": name, "arguments": arguments}})
        response = wait_response(proc, 2)
        if not response:
            raise RuntimeError(f"tools/call {name} timed out")
        return response
    finally:
        try:
            proc.kill()
        except OSError:
            pass


def load_session():
    if SESSION_FILE.exists():
        try:
            return json.loads(SESSION_FILE.read_text(encoding="utf-8")).get("design_session_id")
        except json.JSONDecodeError:
            return None
    return None


def save_session(text):
    marker = '"design_session_id"'
    index = text.find(marker)
    while index != -1:
        chunk = text[index:index + 200]
        colon = chunk.find(":")
        if colon != -1:
            candidate = chunk[colon + 1:chunk.find(",", colon)]
            session_id = candidate.strip().strip('"}')
            if session_id:
                SESSION_FILE.write_text(json.dumps({"design_session_id": session_id}, indent=2), encoding="utf-8")
                return session_id
        index = text.find(marker, index + 1)
    return None


def main():
    if len(sys.argv) < 2:
        print(__doc__)
        return 2

    proc = spawn()
    try:
        send(proc, {"jsonrpc": "2.0", "id": 1, "method": "initialize", "params": {
            "protocolVersion": PROTOCOL,
            "capabilities": {},
            "clientInfo": {"name": "prax-bypass", "version": "1.0"},
        }})
        if not wait_response(proc, 1):
            raise RuntimeError("initialize timed out")
        send(proc, {"jsonrpc": "2.0", "method": "notifications/initialized"})

        if sys.argv[1] == "--list":
            send(proc, {"jsonrpc": "2.0", "id": 3, "method": "tools/list"})
            response = wait_response(proc, 3)
            tools = response.get("result", {}).get("tools", []) if response else []
            TOOLS_FILE.write_text(json.dumps(tools, indent=2, ensure_ascii=False), encoding="utf-8")
            print(f"wrote {len(tools)} tool schemas to {TOOLS_FILE}")
            for tool in tools:
                print(f"  {tool.get('name')}")
            return 0

        name = sys.argv[1]
        arguments = json.loads(sys.argv[2]) if len(sys.argv) > 2 and sys.argv[2] != "-" else {}
        inject = "--no-session" not in sys.argv
        if inject and "design_session_id" not in arguments and name != "design_start":
            session_id = load_session()
            if session_id:
                arguments["design_session_id"] = session_id

        send(proc, {"jsonrpc": "2.0", "id": 2, "method": "tools/call", "params": {"name": name, "arguments": arguments}})
        response = wait_response(proc, 2)
        if not response:
            print(f"ERROR: {name} timed out", file=sys.stderr)
            return 1
        if "error" in response:
            print("RPC ERROR:", json.dumps(response["error"], ensure_ascii=False))
            return 1
        content = response.get("result", {}).get("content", [])
        text = "\n".join(item.get("text", "") for item in content)
        saved = save_session(text)
        if saved:
            print(f"[session {saved}]")
        print(text)
        return 0
    finally:
        try:
            proc.kill()
        except OSError:
            pass


if __name__ == "__main__":
    sys.exit(main())

