function deriveImpact(graph: SemanticGraph, selectedId: string): CanvasImpactView {
  const upstreamObjectIds = new Set<string>();
  const downstreamObjectIds = new Set<string>();
  const upstreamRelationshipIds = new Set<string>();
  const downstreamRelationshipIds = new Set<string>();
  for (const relationship of graph.relationships) {
    const selectedIsTarget = relationship.targetObjectId === selectedId;
    const selectedIsSource = relationship.sourceObjectId === selectedId;
    if (!selectedIsTarget && !selectedIsSource) continue;
    const flowsIntoSelected = selectedIsTarget;
    const flowsAwayFromSelected = selectedIsSource;
    if (flowsIntoSelected) {
      upstreamRelationshipIds.add(relationship.id);
      upstreamObjectIds.add(selectedIsTarget ? relationship.sourceObjectId : relationship.targetObjectId);
    }
    if (flowsAwayFromSelected) {
      downstreamRelationshipIds.add(relationship.id);
      downstreamObjectIds.add(selectedIsSource ? relationship.targetObjectId : relationship.sourceObjectId);
    }
  }
  upstreamObjectIds.delete(selectedId);
  downstreamObjectIds.delete(selectedId);
  return { subjectId: selectedId, upstreamObjectIds, downstreamObjectIds, upstreamRelationshipIds, downstreamRelationshipIds };
}

