export type CanvasRelationshipEdge = Edge<RelationshipEdgeData, "relationship">;

function handleId(side: "left" | "right" | "top" | "bottom", role: "source" | "target") {
  return `${role}-${side}`;
}

function impactRoleForObject(view: CanvasViewModel, objectId: string): ImpactRole | undefined {
  const impact = view.impact;
  if (!impact) return undefined;
  const upstream = impact.upstreamObjectIds.has(objectId);
  const downstream = impact.downstreamObjectIds.has(objectId);
  if (upstream && downstream) return "both";
  if (upstream) return "upstream";
  if (downstream) return "downstream";
  return undefined;
}

function impactRoleForRelationship(view: CanvasViewModel, relationshipId: string): ImpactRole | undefined {
  const impact = view.impact;
  if (!impact) return undefined;
  const upstream = impact.upstreamRelationshipIds.has(relationshipId);
  const downstream = impact.downstreamRelationshipIds.has(relationshipId);
  if (upstream && downstream) return "both";
  if (upstream) return "upstream";
  if (downstream) return "downstream";
  return undefined;
}

function flowTransition(
  steps: SemanticFlowStep[],
  sourceObjectId: string,
  targetObjectId: string,
) {
  const stepById = new Map(steps.map((step) => [step.id, step]));
  for (const step of steps) {
    if (step.objectId !== sourceObjectId) continue;
    const next = step.nextStepIds.map((id) => stepById.get(id)).find((candidate) => candidate?.objectId === targetObjectId);
