function stubLayout(graph) {
  return {
    graphId: graph.id,
    fingerprint: `stub:${graph.id}`,
    orientation: "RIGHT",
    width: 1000,
    height: 800,
    durationMs: 0,
    objectRects: Object.fromEntries(graph.objects.map((object, index) => [object.id, { id: object.id, x: (index % 5) * 240, y: Math.floor(index / 5) * 180, width: 232, height: 124 }])),
    regionRects: Object.fromEntries(graph.regions.map((region, index) => [region.id, { id: region.id, x: 0, y: 0, width: 1200, height: 900, depth: index === 0 ? 0 : 1 }])),
    relationshipRoutes: Object.fromEntries(graph.relationships.map((relationship, index) => [relationship.id, { id: relationship.id, points: [{ x: 0, y: index * 10 }, { x: 100, y: index * 10 }], sourceSide: "right", targetSide: "left" }])),
  };
}

test("selected-object impact emphasis separates upstream from downstream", () => {
  const selected = MEDIUM_CANVAS_FIXTURE.objects[1];
  const expectedUpstream = new Set(MEDIUM_CANVAS_FIXTURE.relationships.filter((relationship) => relationship.targetObjectId === selected.id).map((relationship) => relationship.sourceObjectId));
  const expectedDownstream = new Set(MEDIUM_CANVAS_FIXTURE.relationships.filter((relationship) => relationship.sourceObjectId === selected.id).map((relationship) => relationship.targetObjectId));
  assert.ok(expectedUpstream.size > 0 && expectedDownstream.size > 0, "Medium object 001 must have both directions");

  const inspect = deriveCanvasView(MEDIUM_CANVAS_FIXTURE, {
    mode: "inspect",
    selection: { kind: "object", id: selected.id },
    activeFlowId: null,
    zoom: .9,
    searchQuery: "",
  });
  assert.equal(inspect.impact?.subjectId, selected.id);
  assert.deepEqual([...inspect.impact.upstreamObjectIds].sort(), [...expectedUpstream].sort());
  assert.deepEqual([...inspect.impact.downstreamObjectIds].sort(), [...expectedDownstream].sort());
  assert.equal(inspect.objectEmphasis.get(selected.id), "primary");
  for (const objectId of expectedUpstream) assert.equal(inspect.objectEmphasis.get(objectId), "related", `upstream ${objectId} must stay figure`);
  for (const objectId of expectedDownstream) assert.equal(inspect.objectEmphasis.get(objectId), "related", `downstream ${objectId} must stay figure`);
  const unrelated = MEDIUM_CANVAS_FIXTURE.objects.filter((object) => object.id !== selected.id && !expectedUpstream.has(object.id) && !expectedDownstream.has(object.id));
  assert.ok(unrelated.length > 0);
  for (const object of unrelated) assert.equal(inspect.objectEmphasis.get(object.id), "muted", `unrelated ${object.id} must recede`);
  for (const relationship of MEDIUM_CANVAS_FIXTURE.relationships) {
    const incident = relationship.sourceObjectId === selected.id || relationship.targetObjectId === selected.id;
    assert.equal(inspect.relationshipEmphasis.get(relationship.id), incident ? "active" : "muted");
  }

  const projected = projectSemanticGraph(MEDIUM_CANVAS_FIXTURE, stubLayout(MEDIUM_CANVAS_FIXTURE), inspect);
  const nodeById = new Map(projected.nodes.filter((node) => node.type === "object").map((node) => [node.id, node]));
  for (const objectId of expectedUpstream) assert.equal(nodeById.get(objectId)?.data.impactRole, "upstream");
  for (const objectId of expectedDownstream) assert.equal(nodeById.get(objectId)?.data.impactRole, "downstream");
  const unrelatedNode = unrelated.map((object) => nodeById.get(object.id)).find(Boolean);
  assert.equal(unrelatedNode?.data.impactRole, undefined);
  for (const edge of projected.edges) {
    const upstream = inspect.impact.upstreamRelationshipIds.has(edge.id);
    const downstream = inspect.impact.downstreamRelationshipIds.has(edge.id);
    assert.equal(edge.data.impactRole, upstream && downstream ? "both" : upstream ? "upstream" : downstream ? "downstream" : undefined);
  }

  const landscape = visibleObjectIds(MEDIUM_CANVAS_FIXTURE, { ...inspect, zoomLevel: "landscape", zoom: .3 });
  assert.ok(landscape.has(selected.id));
  assert.ok([...expectedUpstream].some((objectId) => landscape.has(objectId)));
  assert.ok([...expectedDownstream].some((objectId) => landscape.has(objectId)));

  const browse = deriveCanvasView(MEDIUM_CANVAS_FIXTURE, { mode: "browse", selection: null, activeFlowId: null, zoom: .68, searchQuery: "" });
  assert.equal(browse.impact, null);
  for (const object of MEDIUM_CANVAS_FIXTURE.objects) assert.equal(browse.objectEmphasis.get(object.id), "normal", "Deselect must return every object to normal");
  for (const relationship of MEDIUM_CANVAS_FIXTURE.relationships) assert.equal(browse.relationshipEmphasis.get(relationship.id), "normal", "Deselect must return every relationship to normal");

  const focus = deriveCanvasView(MEDIUM_CANVAS_FIXTURE, {
    mode: "focus",
    selection: { kind: "object", id: selected.id },
    activeFlowId: null,
    zoom: .9,
    searchQuery: "",
  });
  assert.equal(focus.impact?.subjectId, selected.id, "Focus must keep impact direction on direct neighbors");
  assert.ok([...focus.objectEmphasis.values()].includes("context"), "Focus two-hop context grammar is unchanged");

  const flow = MEDIUM_CANVAS_FIXTURE.flows[0];
  const trace = deriveCanvasView(MEDIUM_CANVAS_FIXTURE, {
    mode: "trace",
    selection: { kind: "flow", id: flow.id },
    activeFlowId: flow.id,
    zoom: .9,
    searchQuery: "",
  });
  assert.equal(trace.impact, null, "Trace lens owns emphasis; impact emphasis must not compete");

  const row = { id: "row", projectId: "p", changeId: "c", knowledgeState: "CONFIRMED", lifecycleStatus: "ACTIVE", validFromRevision: 7, validToRevision: null, sourceObservationId: "obs" };
  const registryGraph = adaptArchitectureToSemanticGraph({
    projectId: "p",
    projectName: "Project",
    revision: 7,
    entities: [
      { ...row, entityKey: "domain", entityType: "Domain", name: "Control Plane", summary: "Boundary", parentEntityKey: null, technology: "", repositoryRefsJson: "[]" },
      { ...row, entityKey: "service", entityType: "Component", name: "Intent Service", summary: "Accepts intent", parentEntityKey: "domain", technology: "TypeScript", repositoryRefsJson: "[]" },
      { ...row, entityKey: "store", entityType: "DataEntity", name: "Evidence Store", summary: "Persists evidence", parentEntityKey: "domain", technology: "D1", repositoryRefsJson: "[]" },
    ],
    relations: [{ ...row, relationKey: "service-store", sourceEntityKey: "service", targetEntityKey: "store", relationType: "depends_on", label: "writes", summary: "", evidenceRefsJson: "[]" }],
    flows: [],
    flowSteps: [],
  });
  const registryView = deriveCanvasView(registryGraph, {
    mode: "inspect",
    selection: { kind: "object", id: "service" },
    activeFlowId: null,
    zoom: .9,
    searchQuery: "",
  });
  assert.deepEqual([...registryView.impact.downstreamObjectIds], ["store"], "Production registry graphs must project impact the same way");

  const bidirectional = {
    ...SMALL_CANVAS_FIXTURE,
    relationships: SMALL_CANVAS_FIXTURE.relationships.slice(0, 1).map((relationship) => ({
      ...relationship,
      sourceObjectId: SMALL_CANVAS_FIXTURE.objects[0].id,
      targetObjectId: SMALL_CANVAS_FIXTURE.objects[1].id,
      direction: "bidirectional",
    })),
  };
  const bidirectionalView = deriveCanvasView(bidirectional, {
    mode: "inspect",
    selection: { kind: "object", id: SMALL_CANVAS_FIXTURE.objects[0].id },
    activeFlowId: null,
    zoom: .9,
    searchQuery: "",
  });
  assert.ok(bidirectionalView.impact.upstreamObjectIds.has(SMALL_CANVAS_FIXTURE.objects[1].id), "Bidirectional impact must count upstream");
  assert.ok(bidirectionalView.impact.downstreamObjectIds.has(SMALL_CANVAS_FIXTURE.objects[1].id), "Bidirectional impact must count downstream");

  const isolated = COMPLEX_CANVAS_FIXTURE.objects[COMPLEX_CANVAS_FIXTURE.objects.length - 1];
  const isolatedIncident = COMPLEX_CANVAS_FIXTURE.relationships.some((relationship) => relationship.sourceObjectId === isolated.id || relationship.targetObjectId === isolated.id);
  if (!isolatedIncident) {
    const isolatedView = deriveCanvasView(COMPLEX_CANVAS_FIXTURE, {
      mode: "inspect",
      selection: { kind: "object", id: isolated.id },
      activeFlowId: null,
      zoom: .9,
      searchQuery: "",
    });
    assert.equal(isolatedView.objectEmphasis.get(isolated.id), "primary");
    assert.equal(isolatedView.impact.upstreamObjectIds.size + isolatedView.impact.downstreamObjectIds.size, 0, "Isolated object has empty impact");
  }
});

