  assert.equal(focus.impact?.subjectId, selected.id, "Focus must keep impact direction on direct neighbors");
  assert.ok([...focus.objectEmphasis.values()].includes("context"), "Focus two-hop context grammar is unchanged");

  const flow = MEDIUM_CANVAS_FIXTURE.flows[0];
  const trace = deriveCanvasView(MEDIUM_CANVAS_FIXTURE, {
    mode: "trace",
    selection: { kind: "flow", id: flow.id },
    activeFlowId: flow.id,
    zoom: .9,
    searchQuery: "",
  });
  assert.equal(trace.impact, null, "Trace lens owns emphasis; impact emphasis must not compete");

  const row = { id: "row", projectId: "p", changeId: "c", knowledgeState: "CONFIRMED", lifecycleStatus: "ACTIVE", validFromRevision: 7, validToRevision: null, sourceObservationId: "obs" };
  const registryGraph = adaptArchitectureToSemanticGraph({
    projectId: "p",
    projectName: "Project",
    revision: 7,
    entities: [
      { ...row, entityKey: "domain", entityType: "Domain", name: "Control Plane", summary: "Boundary", parentEntityKey: null, technology: "", repositoryRefsJson: "[]" },
      { ...row, entityKey: "service", entityType: "Component", name: "Intent Service", summary: "Accepts intent", parentEntityKey: "domain", technology: "TypeScript", repositoryRefsJson: "[]" },
      { ...row, entityKey: "store", entityType: "DataEntity", name: "Evidence Store", summary: "Persists evidence", parentEntityKey: "domain", technology: "D1", repositoryRefsJson: "[]" },
    ],
    relations: [{ ...row, relationKey: "service-store", sourceEntityKey: "service", targetEntityKey: "store", relationType: "depends_on", label: "writes", summary: "", evidenceRefsJson: "[]" }],
    flows: [],
    flowSteps: [],
  });
  const registryView = deriveCanvasView(registryGraph, {
    mode: "inspect",
    selection: { kind: "object", id: "service" },
    activeFlowId: null,
    zoom: .9,
    searchQuery: "",
  });
  assert.deepEqual([...registryView.impact.downstreamObjectIds], ["store"], "Production registry graphs must project impact the same way");

  const bidirectional = {
    ...SMALL_CANVAS_FIXTURE,
    relationships: SMALL_CANVAS_FIXTURE.relationships.slice(0, 1).map((relationship) => ({
      ...relationship,
      sourceObjectId: SMALL_CANVAS_FIXTURE.objects[0].id,
      targetObjectId: SMALL_CANVAS_FIXTURE.objects[1].id,
      direction: "bidirectional",
    })),
  };
  const bidirectionalView = deriveCanvasView(bidirectional, {
    mode: "inspect",
    selection: { kind: "object", id: SMALL_CANVAS_FIXTURE.objects[0].id },
    activeFlowId: null,
    zoom: .9,
    searchQuery: "",
  });
  assert.ok(bidirectionalView.impact.upstreamObjectIds.has(SMALL_CANVAS_FIXTURE.objects[1].id), "Bidirectional impact must count upstream");
  assert.ok(bidirectionalView.impact.downstreamObjectIds.has(SMALL_CANVAS_FIXTURE.objects[1].id), "Bidirectional impact must count downstream");

  const isolated = COMPLEX_CANVAS_FIXTURE.objects[COMPLEX_CANVAS_FIXTURE.objects.length - 1];
  const isolatedIncident = COMPLEX_CANVAS_FIXTURE.relationships.some((relationship) => relationship.sourceObjectId === isolated.id || relationship.targetObjectId === isolated.id);
  if (!isolatedIncident) {
    const isolatedView = deriveCanvasView(COMPLEX_CANVAS_FIXTURE, {
      mode: "inspect",
      selection: { kind: "object", id: isolated.id },
      activeFlowId: null,
      zoom: .9,
      searchQuery: "",
    });
    assert.equal(isolatedView.objectEmphasis.get(isolated.id), "primary");
    assert.equal(isolatedView.impact.upstreamObjectIds.size + isolatedView.impact.downstreamObjectIds.size, 0, "Isolated object has empty impact");
  }
});

