async () => {
  const articles = [...document.querySelectorAll("article.object-node")];
  const target = articles.find((a) => a.textContent.includes("Identity Service 002"));
  target?.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true }));
  await new Promise((resolve) => setTimeout(resolve, 1000));
  const zoomOut = [...document.querySelectorAll(".architecture-controls button")].find((b) => b.getAttribute("title")?.toLowerCase().includes("zoom out") || b.getAttribute("aria-label")?.toLowerCase().includes("zoom out"));
  for (let index = 0; index < 7; index += 1) {
    zoomOut?.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true }));
    await new Promise((resolve) => setTimeout(resolve, 120));
  }
  await new Promise((resolve) => setTimeout(resolve, 900));
  const chip = document.querySelector(".object-impact-chip");
  const label = document.querySelector(".object-node .object-label");
  const chipRect = chip?.getBoundingClientRect();
  const statusbar = document.querySelector(".canvas-statusbar span")?.textContent;
  const computed = chip ? getComputedStyle(chip) : null;
  return {
    statusbar,
    chipText: chip?.textContent,
    chipRect: chipRect ? { w: Math.round(chipRect.width), h: Math.round(chipRect.height), fontPx: computed?.fontSize } : null,
    labelFontPx: label ? getComputedStyle(label).fontSize : null,
    viewport: window.__reactFlowViewport ?? null,
  };
}

async () => {
  const overlay = document.querySelector("vite-error-overlay");
  if (overlay) overlay.shadowRoot?.querySelector("#pause-btn")?.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true }));
  document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true }));
  await new Promise((resolve) => setTimeout(resolve, 800));
  const zoomOut = [...document.querySelectorAll(".architecture-controls button")].find((b) => (b.getAttribute("title") ?? b.getAttribute("aria-label") ?? "").toLowerCase().includes("zoom out"));
  for (let index = 0; index < 7; index += 1) {
    zoomOut?.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true }));
    await new Promise((resolve) => setTimeout(resolve, 120));
  }
  await new Promise((resolve) => setTimeout(resolve, 900));
  return {
