}

async () => {
  const zoomIn = [...document.querySelectorAll(".architecture-controls button")].find((b) => (b.getAttribute("title") ?? b.getAttribute("aria-label") ?? "").toLowerCase().includes("zoom in"));
  for (let index = 0; index < 2; index += 1) {
    zoomIn?.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true }));
    await new Promise((resolve) => setTimeout(resolve, 150));
  }
  const articles = [...document.querySelectorAll("article.object-node")];
  const target = articles.find((a) => a.textContent.includes("Identity Service 002"));
  target?.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true }));
  await new Promise((resolve) => setTimeout(resolve, 1200));
  const chips = [...document.querySelectorAll(".object-impact-chip")];
  const rects = chips.map((chip) => {
    const rect = chip.getBoundingClientRect();
    return { text: chip.textContent.trim(), w: Math.round(rect.width), h: Math.round(rect.height), inViewport: rect.top >= 0 && rect.bottom <= window.innerHeight && rect.left >= 0 && rect.right <= window.innerWidth };
  });
  return {
    mode: document.querySelector(".canvas-statusbar span")?.textContent,
    chipCount: chips.length,
    sample: rects.slice(0, 6),
    minHeight: Math.min(...rects.map((r) => r.h), 999),
    overlayPresent: Boolean(document.querySelector("vite-error-overlay")),
  };
}

